L10_1 = {}
L10_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_1@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 30911
L10_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_IDLE"
L10_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L10_1.m_Pos = "L"
L10_1.m_Talk_KOREA = "두 사람은 가게를 장식할 인테리어 가구를 보러 갔어. 아마 오후엔 돌아올 거야."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "二人はお店に飾るインテリア雑貨を見に行ったわ。\n午後には戻ってくるはずよ。"
L10_1.m_Talk_ENG = "They are away finding furniture for our shop. They will be back by the afternoon."
L10_1.m_Talk_TWN = "她們去找店裡裝潢要用的家具，應該下午才會回來。"
L10_1.m_Talk_THA = "พวกเขาออกไปหาเฟอร์นิเจอร์สำหรับร้านของเรา พวกเขาจะกลับมาในช่วงบ่าย"
L10_1.m_Talk_VTN = "Họ đang đi tìm đồ nội thất cho cửa hàng của chúng ta. Chiều họ sẽ về."
L10_1.m_Talk_SCN = "她们两个人去看店里要用到的装饰家具了。大概下午就回来。"
L10_1.m_Talk_DEU = "Die beiden schauen im Möbelhaus nach Einrichtungsstücken für das Café. Gegen Mittag sollten sie zurück sein."
L10_1.m_Talk_FRA = "Elles sont allé voir des meubles pour décorer le café. Elles rentreront surement dans l'après-midi."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_1@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 30911
L11_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L11_1.m_Pos = "L"
L11_1.m_Talk_KOREA = "그건 그렇고, 내가 준 레시피들은 한 번 살펴봤니?"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "そういえば、この前渡したレシピにはもう目を通したかしら？"
L11_1.m_Talk_ENG = "Did you take a look at the recipes I gave you?"
L11_1.m_Talk_TWN = "先不說這個，我給你的食譜你看過了嗎？"
L11_1.m_Talk_THA = "คุณดูสูตรที่ฉันให้ไปหรือยัง?"
L11_1.m_Talk_VTN = "Cháu đã xem qua công thức nấu ăn ta đưa chưa?"
L11_1.m_Talk_SCN = "话说，我给你的配方你看过了吗？"
L11_1.m_Talk_DEU = "Übrigens, hast du mal in den Rezepten geschaut, die ich dir gab?"
L11_1.m_Talk_FRA = "Au fait, tu as pu jeter un œil aux recettes que je t'ai données ?"
