L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "わからないところはなかった？"
L12_1.m_Talk_ENG = "Do you have any questions?"
L12_1.m_Talk_TWN = "會很困難嗎？"
L12_1.m_Talk_THA = "คุณมีข้อสงสัยอะไรไหม?"
L12_1.m_Talk_VTN = "Có câu hỏi nào không?"
L12_1.m_Talk_SCN = "有没有不理解的地方？"
