L14_1 = {}
L14_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_1@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 30911
L14_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_LAUGH"
L14_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L14_1.m_Pos = "C"
L14_1.m_Talk_KOREA = "헤헤, 사실 글로만 봐서 아직 뭐가 뭔지 잘 모르겠어요."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "えへへ、一応読んではきたんですけど、文字だけじゃ\nイメージがつかめなくて。"
L14_1.m_Talk_ENG = "Actually, they are all just names, not ingredients, so I don’t really know what’s what."
L14_1.m_Talk_TWN = "嘿嘿，光看文字不太能理解到底是什麼東西。"
L14_1.m_Talk_THA = "จริงๆ แล้วทั้งหมดเป็นเพียงชื่อ ไม่ใช่ส่วนผสม เลยไม่รู้ว่าอะไรคืออะไร"
L14_1.m_Talk_VTN = "Thực ra tất cả đều chỉ là tên gọi chứ không phải thành phần nên cháu thực sự không biết đó là gì."
L14_1.m_Talk_SCN = "嘿嘿，光看文字说明确实有些难以理解。"
L14_1.m_Talk_DEU = "Hehe, ehrlich gesagt finde ich das in geschriebener Form noch etwas schwierig."
L14_1.m_Talk_FRA = "Comme ça sur le papier, j'ai du mal à me faire une idée !"
L15_1 = {}
L15_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_1@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 30911
L15_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_SERIOUS"
L15_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L15_1.m_Pos = "C"
L15_1.m_Crash = 30
L15_1.m_Talk_KOREA = "…특히 여기! 이 맛있어지는 묘약이라는 건 대체 뭔가요? 이거 진짜 레시피에요?"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "……特にここ！　この美味しくなる妙薬っていったい何なんですか？\nこれ、本当にちゃんとしたレシピですか？"
L15_1.m_Talk_ENG = "Especially... here! What is this \"Tasty Potion\"? That's not an ingredient!"
L15_1.m_Talk_TWN = "…像這個！變好吃的秘方到底是什麼？這真的是食譜嗎？"
L15_1.m_Talk_THA = "อย่างเช่น...นี่! \"ยารสอร่อย\" นี้คืออะไร? นั่นไม่ใช่ส่วนผสม!"
L15_1.m_Talk_VTN = "Đặc biệt là... ở đây! \"Thuốc ngon\" này là gì? Đó không phải là một thành phần!"
L15_1.m_Talk_SCN = "……特别是这个！“变得美味的秘药”到底是什么？这是什么东西？"
L15_1.m_Talk_DEU = "... Besonders dieser Teil! Was ist bitte eine „Leckerwerdendes Elixier“? Ist das echt ein Rezept?"
L15_1.m_Talk_FRA = "Surtout celle-ci ! « La potion de goût » ? C'est vraiment une recette ?"
L16_1 = {}
