L17_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L17_1.m_Pos = "C"
L17_1.m_Talk_KOREA = "흐음, 그래… 말로 설명하는 것보다 직접 맛을 보는게 빠를지도 모르겠네."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "うーん、そうね……言葉で説明するより、直接作ってみたほうが\n早いかもね。"
L17_1.m_Talk_ENG = "Maybe you should just try it rather than listen to my explanation."
L17_1.m_Talk_TWN = "嗯嗯，也是…與其口頭說明，不如讓你親自嚐嚐會比較快。"
L17_1.m_Talk_THA = "บางทีคุณควรลองทำมันดู น่าจะเข้าใจกว่าฉันอธิบายเยอะ"
L17_1.m_Talk_VTN = "Có lẽ cháu nên thử nó hơn là nghe ta giải thích."
L17_1.m_Talk_SCN = "嗯……与其费力说明，不如让你亲自品尝下吧。"
L17_1.m_Talk_DEU = "Hmm, ja ... Probieren geht über Studieren."
L17_1.m_Talk_FRA = "Hmm... Essayons d'en préparer une, ce sera plus simple que de t'expliquer."
