L18_1.m_Talk_KOREA = "그럼 어디 한 번 레시피를 같이 만들어 볼까?"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "それじゃあ、一緒に作ってみましょうか。"
L18_1.m_Talk_ENG = "Let’s make it together."
