L23_1 = {}
L23_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_1@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 30911
L23_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L23_1.m_Pos = "L"
L23_1.m_Talk_KOREA = "커피는 우리에게 무척 친숙한 음료지만, 사실 아주 민감한 아이란다."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "コーヒーって身近な飲み物だけど、実はとても繊細な子なの。"
L23_1.m_Talk_ENG = "You see, coffee is very common, but it’s also a very delicate drink."
L23_1.m_Talk_TWN = "雖然咖啡是我們很熟悉的飲品，但是其實咖啡是很敏感的。"
L23_1.m_Talk_THA = "คุณเห็นรึยังว่าการชงกาแฟเป็นเรื่องง่ายมากๆ แต่ก็เป็นเครื่องดื่มที่ละเอียดอ่อนมากเช่นกัน"
L23_1.m_Talk_VTN = "Cháu thấy đấy, cà phê rất phổ biến nhưng cũng là một thức uống rất tinh tế."
L23_1.m_Talk_SCN = "咖啡虽然是我们很熟悉的饮料，但其实冲咖啡也有很多讲究。"
L23_1.m_Talk_DEU = "Kaffee ist uns als Getränk sehr vertraut, erfordert aber viel Feingefühl."
L23_1.m_Talk_FRA = "En dépit de son aspect familier, le café est un breuvage extrêmement subtil."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_1@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 30911
L24_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_IDLE"
L24_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L24_1.m_Pos = "L"
L24_1.m_Talk_KOREA = "추출 방식, 추출 시간, 원두의 질과 양 등 여러가지 조건에 따라 맛이 달라지지."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "淹れ方や蒸らす時間、豆の質や量など、様々な条件で\n味が変わるわ。"
L24_1.m_Talk_ENG = "Its taste changes depending on the method and time of extraction, as well as quality and quantity of beans."
L24_1.m_Talk_TWN = "無論是萃取的方式和時間，或是咖啡豆的品質和份量，都會影響到咖啡的味道。"
L24_1.m_Talk_THA = "รสชาติจะเปลี่ยนไปขึ้นอยู่กับวิธีการและเวลาในการสกัด รวมถึงคุณภาพและปริมาณของเมล็ดกาแฟด้วย"
L24_1.m_Talk_VTN = "Hương vị của nó thay đổi tùy thuộc vào phương pháp và thời gian chiết xuất, cũng như chất lượng và số lượng hạt."
L24_1.m_Talk_SCN = "咖啡豆的研磨方式，研磨时间，以及品质与数量。根据不同的条件，味道也会变得千差万别。"
L24_1.m_Talk_DEU = "Je nach Pressung, Pressdauer, die Qualität und Menge der Bohnen und mehr Faktoren verändert sich der Geschmack."
L24_1.m_Talk_FRA = "Son arôme varie sensiblement selon la méthode de torréfaction, le temps d'extraction, et la qualité ainsi que la quantité des grains utilisés."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_1@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 30911
L25_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L25_1.m_Pos = "L"
L25_1.m_Talk_KOREA = "그래서 깐깐한 바리스타는 물의 성분까지 따지기도 해."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "だから、几帳面なバリスタだと水の成分にまでこだわることもあるのよ。"
L25_1.m_Talk_ENG = "Some picky baristas even choose the water for their coffee."
L25_1.m_Talk_TWN = "有些講究的咖啡師甚至還會要求水的成分呢。"
L25_1.m_Talk_THA = "บาริสต้าจอมพิถีพิถันบางคนถึงกับเลือกน้ำสำหรับชงกาแฟ"
L25_1.m_Talk_VTN = "Một số thợ pha cà phê kén tới nỗi thậm chí còn chọn nước pha cà phê."
L25_1.m_Talk_SCN = "所以，优秀的咖啡师甚至会考虑水的成分。"
L25_1.m_Talk_DEU = "Deshalb achten strenge Baristas sogar auf die Zusammensetzung des Wassers."
L25_1.m_Talk_FRA = "Les baristas les plus exigeants ajouteront à ça les éléments présents dans l'eau ajoutée à la préparation."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_1@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 30911
L26_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L26_1.m_Pos = "R"
L26_1.m_Crash = 30
L26_1.m_Talk_KOREA = "그, 그렇게까지요?"
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "そ、そこまでするんですか？"
L26_1.m_Talk_ENG = "W-wow, that sounds very complicated."
L26_1.m_Talk_TWN = "這麼誇張喔？"
L26_1.m_Talk_THA = "ว้าว ฟังดูซับซ้อนมาก"
L26_1.m_Talk_VTN = "W-wow, nghe có vẻ phức tạp quá."
L26_1.m_Talk_SCN = "有、有必要那么夸张吗？"
L26_1.m_Talk_DEU = "I-ist das echt nötig?"
L26_1.m_Talk_FRA = "Vraiment, à ce point-là ?"
L27_1 = {}
L27_1.m_CutScenProcessKey = 27
