L28_1 = {}
L28_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_1@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 30911
L28_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_DESPAIR"
L28_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L28_1.m_Pos = "C"
L28_1.m_Talk_KOREA = "저는 다 비슷비슷한 것 같던데……."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "私には違いがよくわかりませんが……"
L28_1.m_Talk_ENG = "But it all seems the same to me..."
L28_1.m_Talk_TWN = "我覺得喝起來都差不多說……"
L28_1.m_Talk_THA = "แต่ทุกอย่างมันก็เหมือนกันสำหรับฉัน..."
L28_1.m_Talk_VTN = "Nhưng đối với cháu thì tất cả đều giống nhau..."
L28_1.m_Talk_SCN = "我倒是觉得味道都差不多……"
L28_1.m_Talk_DEU = "Ich fand immer, dass alles ziemlich ähnlich schmeckt ..."
L28_1.m_Talk_FRA = "Personnellement, je ne fais pas trop la différence..."
L29_1 = {}
L29_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_1@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 30911
L29_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_LAUGH"
L29_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L29_1.m_Pos = "C"
L29_1.m_Crash = 30
L29_1.m_Talk_KOREA = "후후, 손님 입장에서는 그럴 수도 있지."
L29_1.m_fTalkTime = 0.03
L30_1 = "ふふ、お客さんの立場だとそうかもね。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Well, customers might know no difference."
L29_1.m_Talk_ENG = L30_1
L30_1 = "呵呵，以客人的角度來說可能很難分辨其中的差異。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ลูกค้าอาจจะไม่ทราบถึงความแตกต่าง"
L29_1.m_Talk_THA = L30_1
L30_1 = "Chà, khách hàng có thể không biết sự khác biệt."
L29_1.m_Talk_VTN = L30_1
L30_1 = "呼呼。也许在顾客的角度来看是这样吧。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Hoho, aus der Sicht der Kunden kann das schon sein."
L29_1.m_Talk_DEU = L30_1
L30_1 = "C'est normal, tu es une simple conssomatrice."
L29_1.m_Talk_FRA = L30_1
