L32_1 = {}
L33_1 = "COUNTERCASE_YUNA_NORMAL_1@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 30911
L32_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_LAUGH"
L32_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L32_1.m_Pos = "L"
L33_1 = "하지만 그 비슷비슷해 보이는 맛 역시 손님을 위한 최선의 결과인 거야."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "でも、たとえ似たような味だとしても、お客さんのことを考えた\n最善の結果なのよ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "But even “the same” tastes are the results of these particular choices."
L32_1.m_Talk_ENG = L33_1
L33_1 = "不過每位客人喝到的味道，都是咖啡師用心沖泡的結果。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แต่ถึงแม้รสนิยม \"เหมือนกัน\" ก็ยังเป็นผลมาจากตัวเลือกเหล่านี้"
L32_1.m_Talk_THA = L33_1
L33_1 = "Nhưng ngay cả những sở thích “giống nhau” cũng là kết quả của những lựa chọn cụ thể này."
L32_1.m_Talk_VTN = L33_1
L33_1 = "但就算他们觉得味道都差不多，我们也要为了顾客尽最大努力。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Aber selbst diese ähnlichen Aromen sind ein Resultat von bestmöglicher Mühe für die Kunden."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Mais même ça, cette ressemblance des arômes d'un café à l'autre, c'est le résultat d'un long travail."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "COUNTERCASE_YUNA_NORMAL_1@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 30911
L33_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L33_1.m_Pos = "R"
L34_1 = "우와, 뭔가 대단한 것 같아요! 마치 선의의 경쟁이라는 느낌……?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "うわあ、なんかすごいですね！　まるで競い合っているような……？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Wow, that’s amazing! So it’s like everyone is competing against each other?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "哇喔，感覺好厲害喔！原來每杯咖啡的背後都藏有咖啡師的心意……"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ว้าว น่าทึ่งมาก! เหมือนทุกคนแข่งขันกันเองเหรอยังงั้นหรอ?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Ồ, thật tuyệt với! Vậy có vẻ như mọi người đang cạnh tranh với nhau?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "呜哇，听起来好厉害！就像是一种味道的竞争……？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Wow, das klingt beeindruckend! Fast wie ein freundschaftlicher Wettbewerb ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Wouah, incroyable ! Une sorte de rivalité amicale... ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "COUNTERCASE_YUNA_NORMAL_1@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 30911
L34_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_IDLE"
L34_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L34_1.m_Pos = "L"
L35_1 = "하지만 유나의 말도 일 리가 있어. 비슷비슷한 맛 사이에서 살아남으려면 자기만의 개성이 필요하거든."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "まあ、ユナのいうとおりかも。似たような味の中で生き残るには、\n自分だけの個性も必要でしょうね。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Yes. But you do have a point. Because all coffee tastes quite similar, each cafe has to find its own unique characteristics to sell its products."
L34_1.m_Talk_ENG = L35_1
L35_1 = "不過你說的也沒錯，咖啡喝起來都差不多，要做出差異性的話就需必須要有自己的特色。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ใช่ แต่คุณมีตัวเลือก เนื่องจากกาแฟทุกชนิดมีรสชาติค่อนข้างคล้ายกัน แต่ละร้านกาแฟจึงต้องค้นหาลักษณะเฉพาะของตนเองเพื่อจำหน่ายผลิตภัณฑ์"
L34_1.m_Talk_THA = L35_1
L35_1 = "Đúng. Nhưng cháu có lý. Bởi vì tất cả các loại cà phê có hương vị khá giống nhau nên mỗi quán cà phê phải tìm ra những đặc trưng riêng để bán sản phẩm của mình."
L34_1.m_Talk_VTN = L35_1
L35_1 = "不过尤娜说得也没错。在差不多味道的竞争中，想要生存下来，就需要有自己独特的个性。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Du hast aber schon einen guten Punkt genannt. Man braucht seine individuelle Note, um unter ähnlichen Aromen hervorzustechen. "
L34_1.m_Talk_DEU = L35_1
L35_1 = "Mais tu n'as pas tort, Yuna. Pour pouvoir se distinguer des autres, chaque café doit posséder une particularité propre."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 30911
