L35_1.m_bClear = true
L36_1 = {}
L37_1 = "COUNTERCASE_YUNA_NORMAL_1@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 30911
L36_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_PRIDE"
L37_1 = "FX_CUTSCEN_NOISE_RUSTLE_03"
L36_1.m_StartFXSoundName = L37_1
L36_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "그래서 우리 카페는 이걸 쓴 단다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "だから、うちのカフェではこれを使うのよ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "And this is our ace in the hole."
L36_1.m_Talk_ENG = L37_1
L37_1 = "而我們的咖啡廳就是使用這個。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "และนี่คือเอซของเราในหลุม"
L36_1.m_Talk_THA = L37_1
L37_1 = "Và đây là con át chủ bài của chúng ta."
L36_1.m_Talk_VTN = L37_1
L37_1 = "所以我们的咖啡店就要用这个。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Deshalb verwendet unser Café dies hier."
L36_1.m_Talk_DEU = L37_1
L37_1 = "C'est pourquoi nous utilisons ceci."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "COUNTERCASE_YUNA_NORMAL_1@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
