L46_1 = "오호, 손재주가 대단한 걸? 잉그리드가 만들었던 첫 음료보다 훨씬 맛있어."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "へえ、手際いいわね。イングリッドが初めて作ったものより\nずっと美味しいわ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Oh, you’re pretty good. It tastes much better than the first drink that Ingrid made."
L45_1.m_Talk_ENG = L46_1
L46_1 = "哇喔，手藝不錯喔？比英格麗第一次泡的好喝很多呢。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "โอ้ มันค่อนข้างดี รสชาติดีกว่าเครื่องดื่มอันแรกที่อิงกริดทำมาก"
L45_1.m_Talk_THA = L46_1
L46_1 = "Ồ, khá đó. Nó có vị ngon hơn nhiều với món đầu tiên mà Ingrid pha."
L45_1.m_Talk_VTN = L46_1
L46_1 = "哎呦，看来你很有天分哦？比英格丽第一次调配时要好喝很多。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Oho, du bist geschickt! Das schmeckt viel besser als der erste Versuch, den Ingrid herstellte."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Tu es plutôt douée ! Il est bien meilleur que la toute première boisson préparée par Ingrid."
L45_1.m_Talk_FRA = L46_1
