L48_1.m_Talk_JPN = L49_1
L49_1 = "Now, let me add a drop of this..."
L48_1.m_Talk_ENG = L49_1
L49_1 = "現在再加入一滴這個……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ตอนนี้ขอเพิ่มอีกหน่อยนะ ..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Bây giờ, hãy để ta thêm một giọt này..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "现在，在尤娜调配的饮料上，再放入一滴这个……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Nun gebe ich einen Tropfen von dem hier in dein Getränk ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Si on ajoute une goutte de ceci dans le café que tu as préparé..."
