L50_1 = "네? 이건 아까 그 시럽?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "え？　これってさっきのシロップですか？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Oh, isn’t that the “ace in the hole” syrup?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "什麼？這是剛才的糖漿？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "โอ้ นั่นน้ำเชื่อม “เอซ” ไม่ใช่เหรอ?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Ồ, đó không phải là si-rô \"át chủ bài\" sao?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "嗯？这是刚才的糖浆？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Huch? Das Sirup von vorhin?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Hein ? Mais c'est le sirop de tout à l'heure ?"
