L51_1 = 50
L50_1.m_Crash = L51_1
L51_1 = "……오!! 아까보다 초콜릿의 쌉사래한 풍미가 훨씬 살아나는 것 같아요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "……おお！！　さっきよりもチョコのビターな風味が口の中いっぱいに広がります。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "... Hey! I can taste the rich flavor of the chocolate even better!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "……哇！！巧克力特有的苦味似乎更明顯咧？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "... เฮ้! ฉันได้ลิ้มรสช็อคโกแลตที่เข้มข้นยิ่งขึ้นไปอีก!"
L50_1.m_Talk_THA = L51_1
L51_1 = "... A! Cháu có thể nếm được hương vị đậm đà của sô-cô-la thậm chí còn ngon hơn nữa!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "……呜哇！！把巧克力浓厚的味道完全激发出来了，比刚才好喝得多！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "... Wow!!! Die zartbittere Note der Schokolade kommt viel besser hervor als vorhin."
L50_1.m_Talk_DEU = L51_1
L51_1 = "... Oh ! L'arôme du chocolat est devenue plus intense !"
L50_1.m_Talk_FRA = L51_1
