L15_1 = "하, 하하. 그래도 이 묘약만 있으면 분명 대박 날 거예요!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "……あ、あはは。でも、これさえあれば、大繁盛間違いなしです！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Haha... But still, I’m sure this syrup will be a great help for our business."
