L15_1 = "哈，哈哈，總之只要有這個秘方應該會大賣吧！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "555... แต่ยังไงก็มั่นใจว่าน้ำเชื่อมนี้จะช่วยร้านเราได้มากแน่ๆ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Haha... Nhưng cháu vẫn chắc chắn rằng xi-rô này sẽ giúp ích rất nhiều cho công việc kinh doanh của chúng ta."
L14_1.m_Talk_VTN = L15_1
L15_1 = "哈、哈哈。不管怎样，有了这个秘药，生意一定会很好的！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "H-haha. Jedenfalls wird unser Café der Renner, wenn wir dieses Elixier haben!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ha... Ha ha. En tout cas avec ça, vous allez faire un tabac !"
L14_1.m_Talk_FRA = L15_1
