L28_1 = "안녕하세요, 가게 시공 의뢰하셨죠?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "こんにちは、補修工事に参りました。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Hello, I’m the contractor, here for the interior work."
L27_1.m_Talk_ENG = L28_1
L28_1 = "你好，我是來施工的。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "สวัสดีครับ ผมผู้รับเหมา มาตกแต่งภายในครับ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Xin chào, tôi đến làm nội thất."
L27_1.m_Talk_VTN = L28_1
L28_1 = "您好，是您委托店铺装修吗？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Hallo! Sie hatten einen Handwerker bestellt, richtig?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Il y a quelqu'un ? Je suis venu pour les travaux."
L27_1.m_Talk_FRA = L28_1
