L29_1 = "Oh, hello. Come on in."
L28_1.m_Talk_ENG = L29_1
L29_1 = "喔，你來啦，稍等我一下。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "สวัสดีค่ะ เข้ามาได้เลยค่ะ"
