L32_1 = "유나야 잠깐 볼 일 좀 보고 올게. 그동안 혼자 음료 연습 좀 하고 있을래?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ユナ、ちょっと席を外すけど、その間一人でも練習できるよね？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Yuna, I have to take care of this. Could you practice while I’m gone?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "尤娜，我要先去忙，你先在這裡練習製作飲料，OK？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ยูนา ฉันต้องดูแลเรื่องนี้ก่อน คุณช่วยฝึกหัดต่อไปในช่วงที่ฉันไม่อยู่ได้ไหม?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Yuna, ta phải lo việc này. Cháu có thể tập luyện khi ta đi vắng được không?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "尤娜，我得去处理一些事情，你就先自己练习调配饮料吧。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Yuna, ich muss was erledigen. Übst du solange, wie man die Getränke zubereitet?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Yuna, je dois m'absenter. Pendant ce temps, entraine toi à préparer les boissons."
L31_1.m_Talk_FRA = L32_1
