L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "라우라 녀석…… 하여간 사지도 않을 거면서 쫑알쫑알 말만 많다니깐."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ラウラのやつ……買う気もないのにぐちぐち文句ばっかり。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "That Laura... She never buys anything; all she does is whine and complain."
L37_1.m_Talk_ENG = L38_1
L38_1 = "蘿拉這傢伙……又不買東西，還一直唸唸唸。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "นั่นลอร่า... เธอไม่เคยซื้ออะไรเลย สิ่งที่เธอทำก็แค่บ่นและบ่น"
L37_1.m_Talk_THA = L38_1
L38_1 = "Laura đó... Cô ấy chẳng bao giờ mua bất cứ thứ gì; cô ấy toàn than vãn và phàn nàn."
L37_1.m_Talk_VTN = L38_1
L38_1 = "劳拉这个家伙……不买东西，又一直在边上叽叽喳喳。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Mensch, diese Laura ... Sie quasselt mir die ganze Zeit rein und kauft am Ende doch nichts!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Franchement, cette Laura... C'est bien la peine de parler autant pour ne rien acheter !"
L37_1.m_Talk_FRA = L38_1
