L5_1.m_fTalkTime = 0.03
L6_1 = "ではストレガの伝統にならって、新入りが作ったものを\n試食してみようじゃないか。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Okay then. By Strega tradition, I’ll test you, rookie."
L5_1.m_Talk_ENG = L6_1
L6_1 = "那按照史特雷加的傳統，新人做的飲料都要通過我們的考驗，現在就來考試吧？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เอาล่ะ ตามธรรมเนียมของ สเตรก้า ฉันจะทดสอบมือใหม่อย่างคุณเอง"
L5_1.m_Talk_THA = L6_1
L6_1 = "Được thôi. Theo truyền thống của Strega, ta sẽ kiểm tra tân binh."
L5_1.m_Talk_VTN = L6_1
L6_1 = "那么，按照史特雷加的传统，就让我评价下新人调配的饮料吧。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Dann wollen wir doch mal ein Getränk des Neulings testen, ganz nach Strega-Tradition."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Dans ce cas... et si tu me faisais goûter une de tes boissons, la novice ? C'est la tradition de Strega, après tout !"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "COUNTERCASE_YUNA_NORMAL_1@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 30911
L6_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "LAURA_STREGA_EVENT_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "혀가 녹아버릴 만큼 달달한 바닐라 파르페. 한 잔 만들어 봐."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "舌が溶けるように甘いバニラパフェを作ってみろ。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Get me a super crazy sweet Vanilla Parfait."
L6_1.m_Talk_ENG = L7_1
L7_1 = "那就先來個甜死人不償命的香草聖代吧。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ขอวานิลลาพาร์เฟ่ต์แสนหวานสุด ๆ ให้ฉันหน่อย"
L6_1.m_Talk_THA = L7_1
L7_1 = "Làm cho ta một ly Vanilla Parfait siêu ngọt ngào."
L6_1.m_Talk_VTN = L7_1
L7_1 = "给我来一杯让舌头都甜得融化掉的香草芭菲吧。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Mach mir einen Becher Vanille-Parfait, das so süß ist, dass mir die Zunge wegschmilzt."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Je voudrais un parfait à la vanille. Très sucré."
L6_1.m_Talk_FRA = L7_1
