L10_1 = "COUNTERCASE_YUNA_NORMAL_1@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 30911
L9_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_SURPRISE"
L10_1 = "INGRID_STREGA_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "L"
L9_1.m_Crash = 30
L10_1 = "시험이라고? 그런 전통이 있었어? 나 때는 없었던 것 같은데?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "試食って？　そんな伝統あったっけ？　私の時はなかったでしょ？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Test? I didn’t know we had such a tradition. How come I didn’t know about it?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "考試？我們店裡有這種傳統嗎？我好像沒考過欸？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ทดสอบหรอ? ฉันไม่รู้ว่าเรามีธรรมเนียมอะไรเช่นนี้ ทำไมฉันถึงไม่รู้เรื่องนี้ล่ะ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Kiểm tra? Tôi không biết chúng ta có truyền thống như vậy đấy. Tại sao tôi lại không biết nhỉ?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "新人评价？真的有这样的传统吗？我记得以前没有来着？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ein Test? Eine solche Tradition habt ihr? Aber zu meiner Zeit gab es das nicht, soweit ich weiß!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Un test ? Elle date de quand, cette tradition ? J'ai jamais entendu parler de ça, moi !"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
