L12_1 = "COUNTERCASE_YUNA_NORMAL_1@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 30911
L11_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_IDLE"
L12_1 = "LAURA_STREGA_EVENT_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "방금 생겼어. 점장의 말은 곧 법이니까."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "たった今作った。店長の言うことは絶対だ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "It’s a new tradition. I’m the owner of this shop, and I’m the law."
L11_1.m_Talk_ENG = L12_1
L12_1 = "我剛剛才決定的，店長的話就是聖旨。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "มันเป็นธรรมเนียมใหม่ ฉันเป็นเจ้าของร้านนี้ และฉันมีสิทธ์"
L11_1.m_Talk_THA = L12_1
L12_1 = "Đó là một truyền thống mới. Ta là chủ cửa hàng này và ta là luật."
L11_1.m_Talk_VTN = L12_1
L12_1 = "是刚刚定下的。因为在这里店长说了算。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Sie besteht ab jetzt. Denn das Wort des Chefs ist Gesetz."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je viens tout juste de la créer. C'est la patronne qui fait la loi, non ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "COUNTERCASE_YUNA_NORMAL_1@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 30911
L12_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "LAURA_STREGA_EVENT_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "아무튼 빨리 한 잔 만들어 봐. 더워 죽겠으니까."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "とにかく早く作ってみろ。今日は暑くてたまらないからな。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Anyway, fix me a drink. I’m so thirsty."
L12_1.m_Talk_ENG = L13_1
L13_1 = "還不快點做，我都要熱死了。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ยังไงก็ชงเครื่องดื่มให้ฉันหน่อย ฉันกระหายน้ำมาก"
L12_1.m_Talk_THA = L13_1
L13_1 = "Dù sao thì, pha cho ta một ly nhé. Ta khát quá."
L12_1.m_Talk_VTN = L13_1
L13_1 = "别磨蹭了，快给我来一杯。我都要热死了。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Nun mach schon! Ich sterbe vor Hitze."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Allez, assez discuté. Un parfait à la vanille, et que ça saute ! On crève de chaud, ici."
L12_1.m_Talk_FRA = L13_1
