L17_1 = "COUNTERCASE_YUNA_NORMAL_1@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 30911
L16_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_SERIOUS"
L17_1 = "FX_CUTSCEN_NOISE_RUSTLE_02"
L16_1.m_StartFXSoundName = L17_1
L16_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "……어디보자."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "……ええと。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Let’s see..."
L16_1.m_Talk_ENG = L17_1
L17_1 = "……我看看喔。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "มาดูกัน..."
L16_1.m_Talk_THA = L17_1
L17_1 = "Hãy xem nào..."
L16_1.m_Talk_VTN = L17_1
L17_1 = "我看看……"
L16_1.m_Talk_SCN = L17_1
L17_1 = "... Also gut."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Voyons voir..."
L16_1.m_Talk_FRA = L17_1
