L18_1 = "COUNTERCASE_YUNA_NORMAL_1@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 30911
L17_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L17_1.m_Pos = "C"
L17_1.m_Crash = 30
L18_1 = "파르페. 바닐라 아이스크림 베이스를 층을 쌓고…… 견과류 토핑."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "パフェ。バニラアイスをベースに具材を詰めて……\nナッツ類をトッピングして……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "A parfait. First, you spread vanilla ice cream as a base... then use nuts as toppings."
L17_1.m_Talk_ENG = L18_1
L18_1 = "香草聖代就是用香草冰淇淋當基底……然後加上一些堅果當點綴。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "พาร์เฟ่ต์ ขั้นแรก ให้ทาไอศกรีมวานิลลาเป็นฐานก่อน... จากนั้นจึงใช้ถั่วโรยเป็นท็อปปิ้ง"
L17_1.m_Talk_THA = L18_1
L18_1 = "Một món parfait. Đầu tiên, phết kem vani làm lớp nền... sau đó dùng các loại hạt làm lớp phủ bên trên."
L17_1.m_Talk_VTN = L18_1
L18_1 = "把香草冰淇淋像这样一层一层叠起来……然后再洒些碎坚果点缀。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Parfait. Man staple Vanilleeis ... dann Nuss-Topping."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Pour faire un parfait, il faut mettre plusieurs couches de glace à la vanille... et saupoudrer le tout d'éclats de noix."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "COUNTERCASE_YUNA_NORMAL_1@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 30911
L18_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_LAUGH"
L18_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L18_1.m_Pos = "C"
L19_1 = 40
L18_1.m_Crash = L19_1
L19_1 = "……그리고 바닐라 시럽! 달게 해달라고 했으니까 왕창 넣어야지."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "……そして、バニラシロップ！　舌が溶けるように甘いっていうオーダーだから、いっぱいかけないと。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "And vanilla syrup! It’s supposed to be super crazy sweet, so I’ll just pour it in."
L18_1.m_Talk_ENG = L19_1
L19_1 = "……還有香草糖漿！她說要很甜，那要加多一點。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "และน้ำเชื่อมวานิลลา! มันควรจะหวานสุดๆ ที่ฉันจะเทราดลงไป"
L18_1.m_Talk_THA = L19_1
L19_1 = "Và xi-rô vani! Nó là siêu ngọt nên mình sẽ đổ nó vào."
L18_1.m_Talk_VTN = L19_1
L19_1 = "……还有香草糖浆！因为要甜一些，就多放点糖浆吧。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "... Und Vanillesirup! Extra viel, da sie es süß haben wollte."
L18_1.m_Talk_DEU = L19_1
L19_1 = "... Sans oublier le sirop de vanille ! Et beaucoup, vu qu'elle voulait quelque chose de très sucré."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "COUNTERCASE_YUNA_NORMAL_1@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 30911
L19_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_SURPRISE"
L19_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L19_1.m_Pos = "C"
L20_1 = "어? 이거였나? 황금빛 시럽이었으니까 이거 맞겠지?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "あれ？　どれだっけ？　金色のシロップだったから、これで合ってるよね？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Um, is this the syrup? It’s golden, so I guess this is it."
L19_1.m_Talk_ENG = L20_1
L20_1 = "嗯？是這個嗎？金黃色的糖漿？應該沒錯吧？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เอ่อ นี่คือน้ำเชื่อมเหรอ? สีทองๆ ฉันคิดว่ามันน่าจะเป็นอันนี้"
L19_1.m_Talk_THA = L20_1
L20_1 = "Ừm, đây là xi-rô à? Nó màu vàng nên đoán là nó đây."
L19_1.m_Talk_VTN = L20_1
L20_1 = "咦？好像是这个吧？黄金色的糖浆，应该没放错才对？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Huch? Ist es das hier? Es sollte ein goldener Sirup sein, also wird es schon stimmen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Mmm ? C'est fini ? Vu la couleur dorée, on dirait bien que oui."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
