L24_1 = "그리고 마지막으로… 맛있어지는 묘약! 이건 에블린 언니 말대로 한 방울만……"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "そして、仕上げに……美味しくなる妙薬！\nこれはエヴリン姉さんの言ったとおり、一滴だけ……"
L23_1.m_Talk_JPN = L24_1
L24_1 = "As for the final touch, the Tasty Potion! Evelyn said I only need a drop..."
L23_1.m_Talk_ENG = L24_1
L24_1 = "最後是…美味秘方！伊芙琳姊姊說只能加一滴……"
L23_1.m_Talk_TWN = L24_1
L24_1 = "สำหรับสัมผัสสุดท้ายคือ เพิ่มรสชาติอรอย อีฟลินบอกฉันว่าแค่ใส่หยดเดียว..."
L23_1.m_Talk_THA = L24_1
L24_1 = "Về phần cuối cùng, Thuốc ngon! Evelyn nói chỉ cần một giọt..."
L23_1.m_Talk_VTN = L24_1
L24_1 = "最后……再加点变得美味的秘药！就像伊芙琳姐姐叮嘱的那样，就放一滴……"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Und als letztes ... Das Leckerwerdende Elixier! Davon nur ein Tropfen, so wie Evelyn sagte ..."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Et pour finir... La potion de goût ! Juste une goutte, comme l'a dit Evelyn..."
L23_1.m_Talk_FRA = L24_1
