L32_1.m_Pos = "C"
L33_1 = "후후, 라우라가 말한대로 바닐라 시럽도 왕창 넣었다고."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ふふ。ラウラのオーダーどおり、バニラシロップもたっぷり入れたの。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Hehe, I used a lot of vanilla syrup, just as you requested."
L32_1.m_Talk_ENG = L33_1
L33_1 = "呵呵，我有照蘿拉的要求加很多糖漿。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "อิอิ ฉันใส่น้ำเชื่อมวานิลลาเยอะๆ ตามที่คุณขอเลย"
L32_1.m_Talk_THA = L33_1
L33_1 = "Hehe, cháu đã dùng rất nhiều si-rô vani, đúng như yêu cầu."
L32_1.m_Talk_VTN = L33_1
L33_1 = "哈哈。我按照劳拉的要求，放了很多香草糖浆。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Hoho, ich habe sogar extra viel Vanillesirup benutzt, so wie du es wolltest."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Hé hé ! Avec un supplément sirop de vanille, comme tu m'as demandé !"
L32_1.m_Talk_FRA = L33_1
