L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "甘すぎて虫歯になっても知らないよ！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Be careful! It’s super crazy sweet, and it could rot your teeth!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "要是甜到蛀牙我可不負責喔！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ระวังนะ! มันหวานสุด ๆ และมันอาจทำให้ฟันของคุณผุได้!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Hãy cẩn thận! Nó siêu ngọt và có thể làm sâu răng đấy!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "如果吃太多甜食让你蛀牙了，我可不会负责！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich kann nichts dafür, wenn du Karies bekommst, weil es so süß ist!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Il ne faudra pas te plaindre si tu as des caries !"
L33_1.m_Talk_FRA = L34_1
