L41_1 = "どう？　初めてにしては上出来じゃない？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "What do you say, Laura? Pretty good for a first timer, right?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "怎麼樣怎麼樣？以第一次來說算是做得很不錯吧？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "คุณพูดอะไรลอร่า? ทำเวลาได้ค่อนข้างดีสำหรับครั้งแรกว่าไหม?"
