L41_1 = "Thế nào, Laura? Khá tốt cho lần đầu tiên, phải không?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "怎么样，劳拉？对第一次调配的人来说，这种程度算不错了吧？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Na, was meinst du? Für mein erstes Mal nicht schlecht, oder, Laura?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Alors, alors ? Pas mal pour une première, non ?"
