L21_1 = "ダメ！！　今はいいかもしれないけど、薬の効果が切れたら\n私たちラウラに殺されちゃうよ！！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "NO! It may be okay for now, but when the effect wears off, she is going to kill us!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "不好！！那是現在，但等她的藥效過去我們就死定了！！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ไม่นะ! ตอนนี้มันอาจจะโอเค แต่เมื่อหมดฤทธิ์ยาแล้ว  เธอจะฆ่าพวกเรา!"
L20_1.m_Talk_THA = L21_1
L21_1 = "KHÔNG! Hiện tại thì có thể ổn, nhưng khi hết tác dụng, cô ấy sẽ giết chúng ta!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "不行！！虽然暂时没事，但等药效过去，我们两个都死定了！！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Nein!!! Für eine Weile ist das okay, aber sobald die Wirkung nachlässt, sind wir beide so gut wie tot!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Non ! Ce n'est pas grave pour l'instant, mais une fois que les effets de la potion se seront dissipés, ce sera terminé pour nous !"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
