L37_1 = "把这个喂给劳拉，就能中和掉秘药的效果！！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wenn wir Laura damit füttern, können wir bestimmt den Effekt des Elixiers aufheben!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Avec ça, les effets de la potion se dissiperont."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
