L41_1 = "R_M_I"
L40_1.m_Pos = L41_1
L41_1 = "자, 착하지 라우라~. 얌전히 있으면~. 어, 언니가 맛있는 쿠키 줄게요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "さあいい子ね、ラウラ。いい子にしていれば、お、お姉ちゃんたちが\n美味しいクッキーをあげるから。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "You’re a good girl, Laura. Sit here and wait. Then I will give you a yummy cookie."
L40_1.m_Talk_ENG = L41_1
L41_1 = "蘿拉你乖～你乖乖的，姊姊就給你吃好吃的餅乾喔。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "คุณเป็นเด็กดี ลอร่า นั่งรออยู่ตรงนี้ แล้วฉันจะให้คุกกี้แสนอร่อยแก่คุณ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Cô là một cô gái ngoan nhỉ, Laura. Hãy ngồi đây và chờ nhé. Rồi cháu sẽ tặng cô một chiếc bánh quy ngon tuyệt."
L40_1.m_Talk_VTN = L41_1
L41_1 = "小劳拉乖~不要乱跑哦~姐姐给你好吃的曲奇饼干。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "B-brave kleine Laura ... Wenn du lieb bist, kriegst du einen leckeren Keks!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Gentille Laura ! Si tu es sage, je te donnerai un délicieux biscuit."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
