L41_1.m_Pos = "L"
L41_1.m_Crash = 30
L42_1 = "증말? 그럼 얌전히 있을래!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ほんと？　じゃあ、いい子にする！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Reaaally? Okay! I’ll sit here and waity-waity!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "真的嗎？那人家會乖乖！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "จริงเหรอ? โอเค ! ฉันจะนั่งรออยู่ตรงนี้!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Thật sao? Được rồi! Tôi sẽ ngồi đây và đợi đợi!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "真的吗？那我会乖乖的！！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Eeecht? Dann bin ich brav!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "C'est vrai ? Alors je vais être sage !"
L41_1.m_Talk_FRA = L42_1
