L44_1.m_Crash = L45_1
L45_1 = "이제 죠!! 쿠키!!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "大人しく待ったから、クッキーちょ～だい！！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Gimme a cookie! A cookie! Now!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "快給人家吃餅乾！！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แจกคุกกี้! คุกกี้! ตอนนี้!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cho tôi một cái bánh quy! Một cái bánh quy! Ngay!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "现在给我吧！！曲奇饼干！！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Will jetzt! Haben! Keks!!!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Un biscuit ! Donne-le-moi tout de suite !"
L44_1.m_Talk_FRA = L45_1
