L46_1 = "자, 여기 맛있는 쿠키 대령이요!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ほら、ここにおいちいクッキーがありますよ～。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Here you go, a yummy cookie just for you!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "來，給你好吃的餅乾！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "มาแล้ว คุกกี้แสนอร่อยสำหรับคุณโดยเฉพาะ!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Đây rồi, một chiếc bánh quy ngon tuyệt dành riêng cho cô!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "拿好，好吃的曲奇饼干来了！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "So, hier kommt der leckere Keks angeflogen!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Tiens, voilà pour toi !"
