L49_1 = 50
L48_1.m_Crash = L49_1
L49_1 = "라우라 이거 알아. 이거 쓴 거 자나!! 안 묵어!!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ラウラ、これ知ってる。これ苦いやつ！！　嘘つき！！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I know what this is. It’s a bitter cookie! Me no want bitter cookie!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "這個人家知道，這個會苦！！人家才鼻要吃！！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันรู้ว่านี่คืออะไร มันเป็นคุกกี้รสขม! ฉันไม่ต้องการคุกกี้รสขม!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tôi biết đây là gì. Đó là một cái bánh quy đắng! Không muốn bánh quy đắng đơu!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "你骗不了劳拉。这是苦的！！我才不吃呢！！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Laura kennt das. Das ist bitter! Will nicht esseeen!!!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Hé, mais je connais ce biscuit ! C'est amer, c'est pas bon ! J'en veux pas !"
L48_1.m_Talk_FRA = L49_1
