L49_1.m_Face = "UNIT_IDLE"
L49_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L49_1.m_Pos = "R"
L50_1 = "차, 착하지 라우라? 그러지 말고 한 입만 먹자~."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ほ、ほら、いい子だねラウラ？　一口だけ食べてみよっか～。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "L-Laura, be a good girl. Let’s just try this once..."
L49_1.m_Talk_ENG = L50_1
L50_1 = "蘿拉你乖～吃一口就好～"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ล-ลอร่า จะเป็นเด็กดีนะ เรามาลองกันสักครั้ง..."
L49_1.m_Talk_THA = L50_1
L50_1 = "L-Laura, hãy là một cô gái ngoan nào. Chúng ta hãy thử món này một lần..."
L49_1.m_Talk_VTN = L50_1
L50_1 = "要、要乖哦，劳拉？只要吃一口就可以啦~"
L49_1.m_Talk_SCN = L50_1
L50_1 = "K-komm, Laura, sei brav! Iss nur einen Bissen, ja?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Tu es une gentille petite fille Laura, n'est-ce pas ? Allez, ouvre la bouche..."
L49_1.m_Talk_FRA = L50_1
