L51_1 = 50
L50_1.m_Crash = L51_1
L51_1 = "시러! 안 무거! 마덦어! 퉤!!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "やだ！　食べたくない！　美味しくない！　ぺっ！！"
