L51_1 = "鼻要！這個不好吃！噁！！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ไม่นะ! ฉันไม่ต้องการคุกกี้รสขม! มันกินยาก! *น้ำลาย*"
