L27_1 = "후후후. 그 들고양이 같은 라우라가 이런 모습이 된 건 오랜만이네~"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "うふふ。あの野良猫みたいなラウラがこんな状態になったのは\n久しぶりだわ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "It’s been a while since I've seen Laura acting this sweet and soft."
L26_1.m_Talk_ENG = L27_1
L27_1 = "呵呵呵，好久沒看到平常像野貓一樣的蘿拉變成這樣了～"
L26_1.m_Talk_TWN = L27_1
L27_1 = "นานแล้วนะที่ฉันไม่ได้เห็นลอร่าแสดงท่าทีอ่อนหวานและนุ่มนวลขนาดนี้"
L26_1.m_Talk_THA = L27_1
L27_1 = "Lâu lắm rồi tôi mới thấy Laura làm vẻ ngọt ngào và nhẹ nhàng như thế này."
L26_1.m_Talk_VTN = L27_1
L27_1 = "呼呼呼。平时像个小野猫一样的劳拉变成了现在这个样子，真是难得啊~"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Hohoho. Ich habe meine süße kleine Kratzbürste Laura lange nicht mehr in dieser Form erlebt!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Haha, ça faisait longtemps que je n'avais pas vu Laura dans cet état. "
L26_1.m_Talk_FRA = L27_1
