L27_1.m_Pos = "L"
L28_1 = "이렇게 흔치 않은 기회를 놓칠 수는 없잖니?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "こんなチャンス、逃す訳にはいかないじゃない？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I can't miss this rare opportunity."
L27_1.m_Talk_ENG = L28_1
L28_1 = "怎麼可以放過這個好機會呢？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ฉันไม่ควรพลาดโอกาสที่หายากนี้"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tôi không thể bỏ lỡ cơ hội hiếm có này."
L27_1.m_Talk_VTN = L28_1
L28_1 = "我怎么能错过如此千载难逢的机会呢？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Das ist eine seltene Chance, die ich ausnutzen muss!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Autant profiter un peu de cette occasion, non ?"
L27_1.m_Talk_FRA = L28_1
