L33_1 = "어머나~! 그래, 그래~!! 우리 라우라가 많이 무서웠구나?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "あら～！　よしよし。ラウラ、怖かったわね？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Oooh, coochi coochi! My dear Laura, you were so scared, weren’t you?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "好可憐喔～蘿拉乖～你一定嚇壞了吧？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "โอ้ย จุ๊ จุ๊! ลอร่าที่รักของฉัน คุณกลัวมากใช่ไหม"
L32_1.m_Talk_THA = L33_1
L33_1 = "Ôi, coochi coochi! Laura thân yêu của tôi, bé đã rất sợ hãi phải không?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "哎呀~！别哭，别哭~！！我们的小劳拉刚才害怕了吧？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Huch! Ja, ja, meine Kleine! Meine liebe Laura hatte ganz viel Angst, stimmt‘s?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Oh ma petite Laura. Tu as eu peur ? "
L32_1.m_Talk_FRA = L33_1
