L33_1.m_Pos = "L"
L34_1 = "그럼, 언니랑 오랜만에 맛있는 거 먹으러 갈까?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "それじゃあ、久しぶりにお姉ちゃんと美味しいものでも食べに行こうか？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Would you like to go with me and have something delicious?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "我們好久沒去吃好的了，你要和姊姊一起去吃嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "คุณอยากไปทานอะไรอร่อยๆ กับฉันไหม?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Bé có muốn đi cùng thưởng thức món gì ngon không?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "那，要不要跟姐姐一起去吃好吃的？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Wollen wir dann mal was Leckeres essen gehen?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Et si on allait manger quelque chose de délicieux, pour la peine ?"
L33_1.m_Talk_FRA = L34_1
