L38_1 = "유나, 잉그리드. 잠깐 카페 좀 맡아 줄래? 라우라 좀 달래주고 올 테니까."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ユナ、イングリッド。カフェをお願いしてもいいかしら。\nラウラとちょっと出かけてくるわね。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Yuna, Ingrid, would you please take care of the cafe while I’m gone? I’ll be tending to Laura."
L37_1.m_Talk_ENG = L38_1
L38_1 = "尤娜、英格麗，店裡就暫時交給你們囉？我帶蘿拉出去走走。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ยูนา อิงกริด ช่วยดูแลร้านกาแฟในขณะที่ฉันไม่อยู่หน่อยได้ไหม? ฉันจะดูแลลอร่าก่อน"
L37_1.m_Talk_THA = L38_1
L38_1 = "Yuna, Ingrid, trông coi quán cà phê khi ta đi vắng được không? Ta sẽ chăm sóc Laura."
L37_1.m_Talk_VTN = L38_1
L38_1 = "尤娜，英格丽。你们能先照看下店铺吗？我去哄哄劳拉。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Yuna, Ingrid, passt ihr kurz auf das Café auf? Ich gehe Laura trösten."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Yuna, Ingrid. Est-ce que je peux vous confier le café ? Je vais aller réconforter Laura."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
