L42_1 = "…휴우, 그래도 에블린 언니가 빨리 와서 다행이야."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "……ふう、エヴリン姉さんが戻ってきてくれてよかったね。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Phew, I’m glad Evelyn came back earlier than expected."
L41_1.m_Talk_ENG = L42_1
L42_1 = "…呼，幸好伊芙琳姊姊及時回來。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "โล่งอก ที่อีฟลินกลับมาเร็วกว่าที่คาดไว้"
L41_1.m_Talk_THA = L42_1
L42_1 = "Phù, may là Evelyn đã quay lại sớm hơn dự kiến."
L41_1.m_Talk_VTN = L42_1
L42_1 = "……呼。幸好伊芙琳姐姐回来的及时。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "... Puh, ein Glück, dass Evelyn bald gekommen ist!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Pfiou. Heureusement qu'Evelyn est arrivée à temps."
L41_1.m_Talk_FRA = L42_1
