L47_1 = 80
L46_1.m_Crash = L47_1
L47_1 = "…………크, 큰일 났다. 난 몰라."
L46_1.m_Talk_KOREA = L47_1
L47_1 = 0.06
L46_1.m_fTalkTime = L47_1
L47_1 = "……や、やばい……どうしよう……！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "... W-we’re in big trouble."
L46_1.m_Talk_ENG = L47_1
L47_1 = "…………完蛋了，我不管了啦。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "... ร-เรากำลังเจอปัญหาใหญ่"
L46_1.m_Talk_THA = L47_1
L47_1 = "... C-chúng ta đang gặp rắc rối lớn rồi."
L46_1.m_Talk_VTN = L47_1
L47_1 = "……出、出大事了。完蛋了。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "... D-das ist eine Katastrophe. Oh nein."
L46_1.m_Talk_DEU = L47_1
L47_1 = "... Oh non, c'est terrible !"
L46_1.m_Talk_FRA = L47_1
