L51_1 = "어? 잉그리드 갑자기 안색이 파래졌는데? 어디 아파?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "え？　イングリッド、顔が真っ青だよ？　具合でも悪いの？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Ingrid, you’re so pale all of a sudden. Are you alright?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "英格麗？你怎麼突然臉色發白？是身體不舒服嗎？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "อิงกริด คุณหน้าซีดขึ้นมาทันที คุณสบายดีหรือเปล่า?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ingrid, đột nhiên cô xanh xao quá. Có ổn không?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "咦？英格丽，你的脸变绿了？是不舒服吗？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Oh? Ingrid, warum bist du auf einmal so blass? Tut es dir irgendwo weh?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Ingrid ! Ça va ? Tu es toute pâle ! "
L50_1.m_Talk_FRA = L51_1
