L5_1.m_Crash = L6_1
L6_1 = "나 갑자기 배가 좀 아픈 것 같은데……."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "私、急にお腹が痛くなったような……"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I think I’m having a stomachache..."
L5_1.m_Talk_ENG = L6_1
L6_1 = "我突然肚子好痛……"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฉันคิดว่าฉันกำลังปวดท้อง..."
L5_1.m_Talk_THA = L6_1
L6_1 = "Tôi nghĩ tôi bị đau bụng..."
L5_1.m_Talk_VTN = L6_1
L6_1 = "我突然有些肚子疼……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich glaube, ich habe plötzlich Bauchschmerzen ..."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Euh, je crois que j'ai mal au ventre..."
