L7_1 = "그, 그… 그럼, 나 좀 먼저 조퇴 좀 해도 될까?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "そ、それじゃ……私、ちょっと先にあがってもいいかな？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "W-would you mind if I left early today?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "那個…我想要提早下班，可以嗎？"
L6_1.m_Talk_TWN = L7_1
