L6_1.m_Talk_THA = L7_1
L7_1 = "Hôm nay tôi về sớm được không?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "我、我觉得我今天可以早点下班！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "D-darf ich heute früher Feierabend machen?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Bon... Je vais rentrer plus tôt pour me reposer !"
